1	#!/usr/bin/env node
2	// Bundle the MV3 extension into dist/ with esbuild (no config, no framework), then zip it
3	// into dist/crossword-chat.zip — the stable store-uploadable artifact (kebab-cased repo
4	// name, never version-stamped, per the shared chrome-extension-release standard), so a
5	// GitHub Release serves the newest build at a permanent URL:
6	//   …/releases/latest/download/crossword-chat.zip
7	// --dev additionally matches the local fake page (http://localhost:8787) so the whole
8	// voice loop can be rehearsed without an NYT subscription (MT-23).
9	
10	import { build } from 'esbuild';
11	import { execFileSync } from 'node:child_process';
12	import { copyFileSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
13	import { join } from 'node:path';
14	
15	const ROOT = new URL('../..', import.meta.url).pathname;
16	const SRC = join(ROOT, 'extension/src');
17	const DIST = join(ROOT, 'dist');
18	const dev = process.argv.includes('--dev');
19	
20	rmSync(DIST, { recursive: true, force: true });
21	mkdirSync(DIST, { recursive: true });
22	
23	const entries = [
24	  { in: join(SRC, 'background/service-worker.js'), out: join(DIST, 'background.js') },
25	  { in: join(SRC, 'content/content-script.js'), out: join(DIST, 'content.js') },
26	  { in: join(SRC, 'content/main-world.js'), out: join(DIST, 'main-world.js') },
27	  { in: join(SRC, 'options/options.js'), out: join(DIST, 'options.js') },
28	];
29	
30	for (const { in: input, out } of entries) {
31	  await build({
32	    entryPoints: [input],
33	    outfile: out,
34	    bundle: true,
35	    format: 'iife',
36	    target: 'chrome116',
37	    sourcemap: dev ? 'inline' : false,
38	    minify: !dev,
39	  });
40	}
41	
42	copyFileSync(join(SRC, 'options/options.html'), join(DIST, 'options.html'));
43	copyFileSync(join(SRC, 'popup/unsupported.html'), join(DIST, 'unsupported.html'));
44	copyFileSync(join(SRC, 'help/help.html'), join(DIST, 'help.html'));
45	
46	mkdirSync(join(DIST, 'icons'), { recursive: true });
47	for (const px of [16, 32, 48, 128]) {
48	  // Colored (manifest default + supported tabs) and gray (unsupported tabs,
49	  // REQ-LIFE-013) variants; both generated by dev/build/make-store-assets.mjs.
50	  for (const name of [`icon-${px}.png`, `icon-${px}-gray.png`]) {
51	    copyFileSync(join(ROOT, 'extension/icons', name), join(DIST, 'icons', name));
52	  }
53	}
54	
55	const manifest = JSON.parse(readFileSync(join(ROOT, 'extension/manifest.json'), 'utf8'));
56	if (dev) {
57	  const devMatch = 'http://localhost:8787/*';
58	  for (const cs of manifest.content_scripts) cs.matches.push(devMatch);
59	  manifest.host_permissions.push(devMatch);
60	  manifest.name += ' (dev)';
61	}
62	writeFileSync(join(DIST, 'manifest.json'), JSON.stringify(manifest, null, 2));
63	
64	// Zip the bundle (manifest at the zip root — store-uploadable). The entries are enumerated
65	// before the archive is created, so the zip never lists itself; -X drops extra file
66	// attributes for a tidy, byte-stable archive.
67	const ZIP_NAME = 'crossword-chat.zip';
68	execFileSync('zip', ['-rXq', ZIP_NAME, ...readdirSync(DIST)], { cwd: DIST });
69	
70	console.log(`Built ${dev ? 'dev' : 'production'} bundle → dist/ (+ ${ZIP_NAME})  (load dist/ via chrome://extensions → Load unpacked)`);
71

1	#!/usr/bin/env node
2	// Requirements traceability (REQ-NFR-006; schema in dev/docs/REQUIREMENTS.md §14).
3	//
4	// Fails when:
5	//   • an Active requirement has no coverage (no automated test and no manual test mentions it)
6	//   • any test / manual item mentions a requirement ID that the requirements doc doesn't define
7	//   • a requirement heading lacks a Status line
8	// Prints the full coverage matrix either way.
9	
10	import { readFileSync, readdirSync, statSync } from 'node:fs';
11	import { join, relative } from 'node:path';
12	
13	const ROOT = new URL('..', import.meta.url).pathname;
14	const REQ_DOC = join(ROOT, 'dev/docs/REQUIREMENTS.md');
15	const MANUAL_DOC = join(ROOT, 'dev/docs/MANUAL-TESTS.md');
16	const TESTS_DIR = join(ROOT, 'extension-test');
17	const ID_RE = /REQ-[A-Z]+-\d{3}/g;
18	const IGNORED_AREAS = new Set(['FAKE']); // reserved for MT-22's tamper drill
19	
20	function walk(dir, out = []) {
21	  for (const name of readdirSync(dir)) {
22	    const p = join(dir, name);
23	    if (statSync(p).isDirectory()) walk(p, out);
24	    else if (name.endsWith('.test.js')) out.push(p);
25	  }
26	  return out;
27	}
28	
29	const area = (id) => id.split('-')[1];
30	
31	// ---- 1. Definitions from REQUIREMENTS.md -----------------------------------
32	const reqText = readFileSync(REQ_DOC, 'utf8');
33	const lines = reqText.split('\n');
34	const defined = new Map(); // id → {status}
35	const malformed = [];
36	
37	for (let i = 0; i < lines.length; i++) {
38	  const heading = lines[i].match(/^#{3,4}\s+(REQ-[A-Z]+-\d{3})\b/);
39	  if (heading) {
40	    const id = heading[1];
41	    let status = null;
42	    for (let j = i + 1; j < Math.min(i + 6, lines.length); j++) {
43	      const m = lines[j].match(/\*\*Status:\*\*\s*(Active|Planned|Retired)/);
44	      if (m) {
45	        status = m[1];
46	        break;
47	      }
48	    }
49	    if (!status) malformed.push(id);
50	    defined.set(id, { status: status ?? 'Active' });
51	    continue;
52	  }
53	  // Future-work bullets: "**REQ-FUT-001 — ...**" are Planned by construction.
54	  const bullet = lines[i].match(/\*\*(REQ-[A-Z]+-\d{3}) —/);
55	  if (bullet && !defined.has(bullet[1])) defined.set(bullet[1], { status: 'Planned' });
56	}
57	
58	// ---- 2. Coverage mentions ----------------------------------------------------
59	const coverage = new Map(); // id → Set(where)
60	const unknownMentions = []; // {id, where}
61	
62	function recordMentions(text, where) {
63	  for (const id of text.match(ID_RE) ?? []) {
64	    if (IGNORED_AREAS.has(area(id))) continue;
65	    if (!defined.has(id)) {
66	      unknownMentions.push({ id, where });
67	      continue;
68	    }
69	    if (!coverage.has(id)) coverage.set(id, new Set());
70	    coverage.get(id).add(where);
71	  }
72	}
73	
74	for (const file of walk(TESTS_DIR)) {
75	  recordMentions(readFileSync(file, 'utf8'), relative(ROOT, file));
76	}
77	const manualText = readFileSync(MANUAL_DOC, 'utf8');
78	let currentMt = null;
79	for (const line of manualText.split('\n')) {
80	  const mt = line.match(/^###\s+(MT-\d+)/);
81	  if (mt) currentMt = mt[1];
82	  if (/^Covers:/.test(line)) recordMentions(line, `dev/docs/MANUAL-TESTS.md ${currentMt ?? ''}`.trim());
83	}
84	
85	// ---- 3. Report ---------------------------------------------------------------
86	const active = [...defined.entries()].filter(([, d]) => d.status === 'Active').map(([id]) => id);
87	const planned = [...defined.entries()].filter(([, d]) => d.status === 'Planned').map(([id]) => id);
88	const uncovered = active.filter((id) => !coverage.has(id));
89	
90	const byArea = new Map();
91	for (const id of [...defined.keys()].sort()) {
92	  const a = area(id);
93	  if (!byArea.has(a)) byArea.set(a, []);
94	  byArea.get(a).push(id);
95	}
96	
97	console.log('Requirements coverage matrix');
98	console.log('============================');
99	for (const [a, ids] of byArea) {
100	  console.log(`\n${a}`);
101	  for (const id of ids) {
102	    const { status } = defined.get(id);
103	    const refs = [...(coverage.get(id) ?? [])];
104	    const mark = status !== 'Active' ? '◌' : refs.length ? '✅' : '❌';
105	    const detail = status !== 'Active'
106	      ? `${status} (not enforced)`
107	      : refs.length ? refs.join(', ') : 'NO COVERAGE';
108	    console.log(`  ${mark} ${id}  ${detail}`);
109	  }
110	}
111	
112	console.log(`\nActive: ${active.length}  Planned: ${planned.length}  Covered: ${active.length - uncovered.length}/${active.length}`);
113	
114	let failed = false;
115	if (malformed.length) {
116	  failed = true;
117	  console.error(`\n✗ Requirement heading(s) missing a **Status:** line: ${malformed.join(', ')}`);
118	}
119	if (uncovered.length) {
120	  failed = true;
121	  console.error(`\n✗ Active requirement(s) without any test coverage:\n  ${uncovered.join('\n  ')}`);
122	}
123	if (unknownMentions.length) {
124	  failed = true;
125	  console.error('\n✗ Mention(s) of requirement IDs not defined in dev/docs/REQUIREMENTS.md:');
126	  for (const { id, where } of unknownMentions) console.error(`  ${id} in ${where}`);
127	}
128	
129	if (failed) process.exit(1);
130	console.log('\n✓ Every Active requirement is covered; no phantom IDs.');
131

1	// The single visual-comparison engine for every pixel-asserted UI requirement.
2	// Each case (dev/requirements/ui/cases/*.case.js) renders the SHIPPED code for one
3	// UI state to a PNG; the result is compared pixel-by-pixel (pixelmatch) against the
4	// committed golden beside it (cases/<name>.png). So the goldens track the shipped
5	// code directly — there is no hand-maintained copy of the button art or the toolbar
6	// markup. Run `npm run refresh:ui` to regenerate after an intentional UI change and
7	// commit the PNGs, so a reviewer sees the before/after in the diff.
8	//
9	// The satori/resvg cases are deterministic (bundled fonts, no browser), so they must
10	// match EXACTLY — any differing pixel is a real change. The Playwright page/popup
11	// cases are real browser screenshots and carry minor cross-environment antialiasing
12	// variance, so each declares a small `maxDiffRatio`; a case without one demands 0.
13	
14	import { describe, test, expect } from 'vitest';
15	import { readFileSync, existsSync, writeFileSync, unlinkSync } from 'node:fs';
16	import { PNG } from 'pngjs';
17	import pixelmatch from 'pixelmatch';
18	import { loadCases, snapshotPath } from './cases.js';
19	import { artifactPath } from './render/artifacts-dir.js';
20	import { applyGallery, REQ_DOC } from './build-gallery.mjs';
21	import { chromiumAvailable } from './render/page-to-png.js';
22	
23	const cases = await loadCases();
24	const hasBrowser = chromiumAvailable();
25	
26	describe('UI visual snapshots', () => {
27	  test('there is at least one UI case', () => {
28	    expect(cases.length).toBeGreaterThan(0);
29	  });
30	
31	  // Any text in a golden (the toolbar labels) is rendered from the bundled font at
32	  // the runtime's locale. The goldens are authored under the CI/sandbox default
33	  // (en-US); guard it so a maintainer on a non-English shell gets an actionable
34	  // message instead of a baffling text-only pixel diff.
35	  test('the environment resolves to the en-US locale the goldens assume', () => {
36	    const locale = new Intl.DateTimeFormat().resolvedOptions().locale;
37	    expect(
38	      locale,
39	      `UI goldens are authored in en-US, but this environment resolves to "${locale}". ` +
40	        'Unset LANG/LC_ALL (or set LANG=C.UTF-8) when running/regenerating the UI snapshots.',
41	    ).toBe('en-US');
42	  });
43	
44	  // §7: the requirements doc embeds these goldens under managed markers. It's derived
45	  // output — fail if it drifts from the generator (run `npm run refresh:ui` to fix).
46	  test('the requirements-doc UI gallery is up to date', () => {
47	    const doc = readFileSync(REQ_DOC, 'utf8');
48	    expect(applyGallery(doc, cases), 'dev/docs/REQUIREMENTS.md UI gallery is stale — run "npm run refresh:ui"').toBe(doc);
49	  });
50	
51	  for (const testCase of cases) {
52	    // A browser case self-skips where no Chromium is present (a CI runner without it),
53	    // so the satori/resvg cases still gate and the run stays green.
54	    const skip = testCase.engine === 'browser' && !hasBrowser;
55	    test.skipIf(skip)(`${testCase.name} (${testCase.description}) matches its golden`, async () => {
56	      const pngBuffer = await testCase.render();
57	      const snapPath = snapshotPath(testCase.name);
58	      const actualPath = artifactPath(`${testCase.name}.actual.png`);
59	      const diffPath = artifactPath(`${testCase.name}.diff.png`);
60	
61	      expect(existsSync(snapPath), `No golden at ${snapPath}; run "npm run refresh:ui" to create one.`).toBe(true);
62	
63	      const actual = PNG.sync.read(pngBuffer);
64	      const expected = PNG.sync.read(readFileSync(snapPath));
65	
66	      if (actual.width !== expected.width || actual.height !== expected.height) {
67	        writeFileSync(actualPath, pngBuffer);
68	        expect.fail(
69	          `${testCase.name}: render size changed: expected ${expected.width}x${expected.height}, ` +
70	            `got ${actual.width}x${actual.height}. See ${actualPath}, or run "npm run refresh:ui" if intentional.`,
71	        );
72	      }
73	
74	      const { width, height } = actual;
75	      const diff = new PNG({ width, height });
76	      const diffPixels = pixelmatch(actual.data, expected.data, diff.data, width, height, { threshold: 0.1 });
77	      const ratio = diffPixels / (width * height);
78	      const maxRatio = testCase.maxDiffRatio ?? 0;
79	
80	      if (ratio > maxRatio) {
81	        writeFileSync(actualPath, pngBuffer);
82	        writeFileSync(diffPath, PNG.sync.write(diff));
83	        expect.fail(
84	          `${testCase.name}: UI changed: ${diffPixels} of ${width * height} pixels differ ` +
85	            `(${(ratio * 100).toFixed(2)}%). See ${actualPath} and ${diffPath}, ` +
86	            'or run "npm run refresh:ui" if intentional.',
87	        );
88	      }
89	      for (const p of [actualPath, diffPath]) if (existsSync(p)) unlinkSync(p);
90	    });
91	  }
92	});
93

1	// Rasterize a jsdom element subtree to a PNG buffer via satori (HTML/CSS-subset ->
2	// SVG) + resvg (SVG -> PNG), with bundled fonts — no browser, so the output is
3	// deterministic and a golden can demand an exact match. Used for the in-page
4	// surface: the REAL mountSessionButton injected into a committed, inline-styled
5	// snapshot of the NYT toolbar (dev/requirements/ui/fixtures/nyt-toolbar.html).
6	//
7	// satori has NO CSS engine: it ignores <style>/<link> and reads only inline
8	// styles. That is exactly why the toolbar fixture is captured with computed styles
9	// already flattened inline, and why our injected button is safe to render — it is
10	// inline-styled and host-CSS-independent by design (brand-icon.js). An <svg> child
11	// (the brand mark) is re-emitted as an <img> of a data-URI SVG, which satori
12	// rasterizes through resvg.
13	
14	import { readFileSync } from 'node:fs';
15	import { fileURLToPath } from 'node:url';
16	import { dirname, join } from 'node:path';
17	import satori from 'satori';
18	import { Resvg } from '@resvg/resvg-js';
19	
20	const FONT_DIR = join(dirname(fileURLToPath(import.meta.url)), 'fonts');
21	const FONT_FAMILY = 'Liberation Sans'; // metric-compatible stand-in for Arial/Helvetica stacks
22	const FONTS = [
23	  { name: FONT_FAMILY, data: readFileSync(join(FONT_DIR, 'LiberationSans-Regular.ttf')), weight: 400, style: 'normal' },
24	  { name: FONT_FAMILY, data: readFileSync(join(FONT_DIR, 'LiberationSans-Bold.ttf')), weight: 700, style: 'normal' },
25	  { name: FONT_FAMILY, data: readFileSync(join(FONT_DIR, 'LiberationSans-Italic.ttf')), weight: 400, style: 'italic' },
26	];
27	
28	const camel = (p) => p.trim().replace(/-([a-z])/g, (_, c) => c.toUpperCase());
29	
30	// Shorthands satori expands by string-parsing (it calls .trim() on the value), so
31	// a coerced number like `border: 0` crashes its expander. Keep these as strings.
32	const STRING_SHORTHANDS = new Set([
33	  'border', 'borderTop', 'borderRight', 'borderBottom', 'borderLeft', 'outline',
34	]);
35	
36	// Properties satori cannot consume: the `font` shorthand it fails to parse
